        if (rst_i) begin
            sck_edge_cnt <= 4'd0;
            sck_edge_detected <= 1'b0;
        end else begin
            if (state == TRANSFER) begin
                if (spi_sck_o) begin
                    sck_edge_cnt <= sck_edge_cnt + 1'b1;
                    if (sck_edge_cnt == 4'd1) begin
                        sck_edge_detected <= 1'b1;
                        sck_edge_cnt <= 4'd0;
                    end
