            rx_sample_reg <= {WORD_WIDTH{1'b0}};
            rx_shift_reg <= {WORD_WIDTH{1'b0}};
        end else begin
            if (sck_edge_detected) begin
                rx_sample_reg <= spi_miso_i;
                // Shift the sampled data into the accumulator
