                    rx_shift_reg <= rx_sample_reg;
                end else begin
                    rx_shift_reg <= {rx_sample_reg, rx_shift_reg[WORD_WIDTH-2:0]};
                end
                bit_count <= bit_count + 1'b1;
            end
        end
    end

